const D = { scale:1, energy:.6, hue:210, speed:1, density:.5, x:.5, y:.55, girth:.55, fluke:.5, seed:0, pose:'auto', style:'ink-wash', act:'surface' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
