const eAmp = P.energy*(.5 + .6*K.intensity);
const kick = Math.min(1.4, K.pulse*(.5+.5*K.intensity) + A.bass*.7);
S.rms = (S.rms||0)*.85 + (A.rms||0)*.15;
S.tre = (S.tre||0)*.8  + (A.treble||0)*.2;
if (S.seedUsed !== P.seed) { S.seedUsed = P.seed; }

// ---- length / form ----
const L = u * 0.92 * P.scale;
const girth = 0.72 + 0.55*P.girth;              // vertical body scale
const flk = (0.11 + 0.11*P.fluke);              // fluke half-span (units of L)
