  const ACT = { surface:['swim','swim','spout','swim'], breach:['swim','breach','breach','sound'], sound:['sound','swim','sound','spout'] };
  const seq = ACT[P.act] || ACT.surface;
  pose = seq[(((K.section%seq.length)+seq.length)%seq.length)];
}
// breach cycle phase (~40-60s), t0-reset tolerant via K.t
const bph = ((K.t*0.022*P.speed + fr(3)) % 1 + 1) % 1;

let lift = 0, pitch = 0, submerge = 0;
const waterY = 0;                                // waterline at anchor y
if (pose === 'breach') {
  // dive-build-leap-splash arc
  const a = bph;
  if (a < 0.45) { submerge = 0.5*Math.sin(a/0.45*Math.PI); pitch = 0.18*Math.sin(a/0.45*Math.PI); }
  else if (a < 0.72) {
    const b = (a-0.45)/0.27; const s = Math.sin(b*Math.PI);
    lift = -s * 0.62; pitch = -0.9*s - 0.5*Math.min(1,b*1.4)*(b>0.5?1:0); submerge = -0.1*s;
    S.splashAt = a; S.splashArm = 1;
  } else {
    if (S.splashArm) { S.splash = 1; S.splashArm = 0; }
    submerge = 0.28*Math.sin((a-0.72)/0.28*Math.PI);
  }
} else if (pose === 'sound') {
  const a = ((K.t*0.05*P.speed + fr(7))%1+1)%1;
  pitch = 0.55*Math.max(0, Math.sin(a*Math.PI));   // fluke-up dive posture
  submerge = 0.22*Math.max(0, Math.sin(a*Math.PI));
} else {
  lift = Math.sin(K.t*0.6 + fr(2)*6) * 0.018 - K.swell*0.02*eAmp;
}
lift += Math.sin(K.t*0.9)*0.01*eAmp;
const driftX = Math.sin(K.t*0.18 + fr(4)*6) * 0.05;

// ---- spout trigger on downbeats ----
const beatIdx = Math.floor(bt);
if (S.lb == null || beatIdx < S.lb) S.lb = beatIdx;
if (beatIdx > S.lb) { const step = beatIdx - S.lb; S.lb = beatIdx; if (((beatIdx%4)+4)%4===0) S.spout = 1; }
S.spout = (S.spout||0)*0.93;
S.splash = (S.splash||0)*0.9;

// ---- tail + undulation params ----
const swim = Math.sin(bt*Math.PI*0.5);              // slow tail phase
const tailAng = swim * (0.42 + 0.35*eAmp) + Math.sin(bt*Math.PI)*0.08*eAmp;
const undAmp = 0.05*eAmp + 0.02;
const undPh  = bt*Math.PI*0.5;

const cx = P.x*width + driftX*L;
const cy = P.y*height + (lift + submerge)*L;

