  const ca = Math.cos(tailAng), sa = Math.sin(tailAng);
  const fl = (dx,dy)=>{ const rx=dx, ry=dy; return [ (sx + rx*ca - ry*sa)*L, ((sy)+ (rx*sa + ry*ca))*L*1 ]; };
  pts.push(fl(0.06,-0.02));
  pts.push(fl(0.155,-flk));
  pts.push(fl(0.12,-0.01));
