  for (let i=0;i<=8;i++){ const px=map(i,0,8,-0.44,0.34); const py=Math.sin(px*3.1-undPh)*undAmp*(0.35+(px+0.5)); curveVertex(px*L, py*L - 0.02*L); }
  endShape();
} else if (st === 'xray') {
  // anatomical / x-ray: pale translucent body + skeleton
