  for (let i=0;i<9;i++){ const px=map(i,0,8,-0.36,0.14); const py=Math.sin(px*3.1-undPh)*undAmp*(0.35+(px+0.5)); const h=(0.12+0.05*Math.sin(i))*girth*L; strokeWeight(u*0.0018);
    line(px*L, py*L-h, px*L+0.01*L, py*L+h); }
