  pop();
}

// eye
if (st!=='contour'){ noStroke(); fill(hue, 30, 8, 90); ellipse(-0.40*L, -0.01*girth*L, 0.022*L, 0.022*L); }
else { noFill(); stroke(hue,12,88,88); strokeWeight(u*0.003); ellipse(-0.40*L,-0.01*girth*L,0.03*L,0.03*L); }
