strokeWeight(u*(st==='engraving'?0.0016:0.003));
beginShape(); curveVertex(-0.50*L,0.02*girth*L); curveVertex(-0.50*L,0.03*girth*L); curveVertex(-0.40*L,0.06*girth*L); curveVertex(-0.28*L,0.07*girth*L); curveVertex(-0.20*L,0.075*girth*L); endShape();

