if (S.splash > 0.03) {
  push(); translate(cx, P.y*height + 0.28*L); blendMode(ADD);
  for (let i=0;i<12;i++){ const ph=fr(i)*TAU; const rr=(0.1+0.9*(1-S.splash))*0.4*L; const sz=(0.03+fr(i+3)*0.05)*L*S.splash;
    fill(hue, 18, 90, 30*S.splash); noStroke(); ellipse(Math.cos(ph)*rr, -Math.abs(Math.sin(ph))*rr*0.5, sz, sz); }
